INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 40, 'theory', 'Quiz: abstract classes');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 0, 'What happens when you create an instance of a class (inherited from ABC) that has an unimplemented @abstractmethod?', '["The method returns None", "TypeError at instantiation", "An error only when the method is called", "Nothing, the method is created automatically"]', 1, 'ABCMeta stores the names of the abstract methods; while the set is not empty, creating an instance is rejected.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 1, 'You applied @abstractmethod but did not inherit the class from ABC. What happens?', '["The class cannot be instantiated", "Python raises a definition error", "The decorator is silently ignored and the instance is created", "The method becomes private"]', 2, 'The check is done by the ABCMeta metaclass; without it, abstract methods forbid nothing.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 2, 'How do you declare an abstract property correctly?', '["@abstractmethod above @property", "@property above @abstractmethod", "Only through a metaclass", "Properties cannot be abstract"]', 1, '@abstractmethod must be closest to the function, with @property above it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 3, 'What is ABC.register(Cls) for?', '["To inherit methods", "To forbid a class", "To make Cls count as a subclass without inheritance (isinstance confirms it)", "To create an instance"]', 2, 'Virtual subclasses attach foreign classes to your hierarchy.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 4, 'What do you need to implement to inherit from collections.abc.Sequence?', '["__len__ and __getitem__ - the rest comes ready", "All the methods of a list", "Only __iter__", "Only __contains__"]', 0, 'Sequence provides iteration, in, count, index and reversed based on __len__ and __getitem__.');
